renames=$(git ls-files -z | tr '\0' '\n' | grep -E '(^|/)renames\.conf$' | head -n1)
[ -n "$renames" ] || exit 1
while IFS= read -r -d '' f; do
  case "$f" in
    *.conf) ;;
    *) continue ;;
  esac
  tmp="$f.rename.$$"
  awk -v mapfile="$renames" '
    BEGIN {
      while ((getline line < mapfile) > 0) {
        if (line ~ /^[[:space:]]*(#|$)/) continue
        eq = index(line, "=")
        if (eq == 0) continue
        old = substr(line, 1, eq - 1)
        new = substr(line, eq + 1)
        gsub(/^[[:space:]]+|[[:space:]]+$/, "", old)
        gsub(/^[[:space:]]+|[[:space:]]+$/, "", new)
        if (old != "" && new != "") ren[old] = new
      }
      close(mapfile)
    }
    {
      if (match($0, /^[[:space:]]*[^[:space:]=]+[[:space:]]*=/)) {
        eq = index($0, "=")
        k = substr($0, 1, eq - 1)
        v = substr($0, eq)
        gsub(/^[[:space:]]+|[[:space:]]+$/, "", k)
        if (k in ren) {
          print ren[k] " " v
          next
        }
      }
      print
    }
  ' "$f" > "$tmp" || { rm -f "$tmp"; exit 1; }
  if cmp -s "$f" "$tmp"; then
    rm -f "$tmp"
  else
    mv "$tmp" "$f"
  fi
done < <(git ls-files --others --ignored --exclude-standard -z)
